module freq_div (
    input CLK_in,
    output reg CLK_50,
    output reg CLK_10,
    output reg CLK_1,
    input RST
);

    reg [0:0] cnt_50;
    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            cnt_50 <= 1'b0;
        end else begin
            cnt_50 <= ~cnt_50;
        end
    end

    reg [3:0] cnt_10;
    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            cnt_10 <= 4'b0;
            CLK_10 <= 1'b0;
        end else if (cnt_10 == 4'd9) begin
            cnt_10 <= 4'b0;
            CLK_10 <= ~CLK_10;
        end else begin
            cnt_10 <= cnt_10 + 1;
        end
    end

    reg [6:0] cnt_100;
    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            cnt_100 <= 7'b0;
            CLK_1 <= 1'b0;
        end else if (cnt_100 == 7'd99) begin
            cnt_100 <= 7'b0;
            CLK_1 <= ~CLK_1;
        end else begin
            cnt_100 <= cnt_100 + 1;
        end
    end

    assign CLK_50 = cnt_50;

endmodule
